```matlab

omega = [-pi:pi/250:pi];

H = h(1) + h(2)*exp(-i*omega) + h(3)*exp(-i*2*omega) + ...

    h(4)*exp(-i*3*omega) + h(5)*exp(-i*4*omega) + ...

    h(6)*exp(-i*5*omega) + h(7)*exp(-i*6*omega) + ...

    h(8)*exp(-i*7*omega);

plot(omega, abs(H));

```

